package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadAuditPort;
import com.example.lending.application.port.out.RecordAuditPort;
import com.example.lending.domain.AuditAction;
import com.example.lending.domain.AuditEntry;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;

@Component
public class AuditPersistenceAdapter implements RecordAuditPort, LoadAuditPort {

    private final AuditLogJpaRepository auditLogJpaRepository;

    public AuditPersistenceAdapter(AuditLogJpaRepository auditLogJpaRepository) {
        this.auditLogJpaRepository = auditLogJpaRepository;
    }

    @Override
    public void recordAudit(AuditEntry entry) {
        auditLogJpaRepository.save(new AuditLogJpaEntity(entry.action().name(), entry.targetId(), entry.memberId(),
                entry.occurredAt()));
    }

    @Override
    public List<AuditEntry> loadAuditByTarget(UUID targetId) {
        return auditLogJpaRepository.findByTargetIdOrderByOccurredAtAscIdAsc(targetId).stream()
                .map(entity -> new AuditEntry(AuditAction.valueOf(entity.getAction()), entity.getTargetId(),
                        entity.getMemberId(), entity.getOccurredAt()))
                .toList();
    }
}

